vec3 palette(float t) {
    // Modified color palette for a different feel
    vec3 a = vec3(0.8, 0.5, 0.4);    // Warmer base color
    vec3 b = vec3(1.4, 1.4, 1.2);    // Reduced contrast
    vec3 c = vec3(2.0, 1.0, 1.0);    // Modified frequency
    vec3 d = vec3(0.8, 1.25, 1.25);  // Phase shift
    return d + b*cos(3.14*(b*t+d));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;
    vec2 uv0 = uv;
    vec3 finalColor = vec3(0.0);



    // Modified pattern generation
    for (float i = 0.0; i < 5.0; i++) {  // Increased iterations for more detail
        // Modified transformation
        uv = fract(uv * 1.8) - 0.5;  // Changed scale factor

        // Modified distance calculation
        float d = length(uv) * exp(-length(uv0));

        // Different color progression
        vec3 col = palette(length(uv0) + i*0.3 + iTime*0.2);  // Slower color change

        // Modified pattern evolution
        d = sin(d*12.0 + iTime*0.8)/10.0;  // Different frequency and amplitude
        d = abs(d);
        d = pow(0.015 / d, 1.4);  // Modified power and threshold

        finalColor += col * d;
    }

    // Add subtle pulsing effect
    finalColor *= 1.0 + 0.1*sin(iTime*0.5);

    // Add vignette effect
    float vignette = 1.0 - length(uv0)*0.5;
    finalColor *= vignette;

    fragColor = vec4(finalColor, 1.0);
}
